import re
from pathlib import Path
violations = []
for path in Path('frontend/src').rglob('*'):
    if path.suffix not in ('.tsx', '.ts') or 'i18n' in path.parts or path.name == 'I18nProvider.tsx':
        continue
    for line in path.read_text().splitlines():
        if re.search(r'[\u4e00-\u9fff]', line) and not line.strip().startswith(('//', '*', '/*', '<!--')):
            violations.append(f'{path}: {line.strip()[:80]}')
assert not violations, '\n'.join(violations)
